1	import { describe, expect, test } from "bun:test";
2	import { BlockId } from "@/lib/world";
3	import { ITEM_DEFS } from "@/lib/game/items";
4	import { MATERIAL_PALETTES, paintGrid, paintIsoBlock, renderSpritePixels, SPRITE_SIZE } from "@/lib/ui/spritePixels";
5	
6	function opaquePixelCount(pixels: Uint8ClampedArray): number {
7	  let count = 0;
8	  for (let i = 3; i < pixels.length; i += 4) if (pixels[i] > 0) count += 1;
9	  return count;
10	}
11	
12	describe("renderSpritePixels", () => {
13	  // Integrity-style: every registered item must produce a real sprite, so a
14	  // new ITEM_DEFS entry without icon coverage fails here instead of falling
15	  // back to the magenta checker silently.
16	  test("every item def yields a non-empty 16x16 sprite", () => {
17	    const placeholder = renderSpritePixels("no_such_item");
18	    for (const def of ITEM_DEFS) {
19	      const pixels = renderSpritePixels(def.id);
20	      expect(pixels.length).toBe(SPRITE_SIZE * SPRITE_SIZE * 4);
21	      expect(opaquePixelCount(pixels)).toBeGreaterThan(20);
22	      expect(pixels).not.toEqual(placeholder); // no item may fall back to the checker
23	    }
24	  });
25	
26	  test("is deterministic", () => {
27	    expect(renderSpritePixels("diamond_sword")).toEqual(renderSpritePixels("diamond_sword"));
28	    expect(paintIsoBlock(BlockId.Grass)).toEqual(paintIsoBlock(BlockId.Grass));
29	  });
30	
31	  test("material tiers produce different sprites for the same shape", () => {
32	    expect(renderSpritePixels("wood_pickaxe")).not.toEqual(renderSpritePixels("diamond_pickaxe"));
33	    expect(renderSpritePixels("wood_sword")).not.toEqual(renderSpritePixels("gold_sword"));
34	    expect(renderSpritePixels("wood_spear")).not.toEqual(renderSpritePixels("diamond_spear"));
35	  });
36	
37	  test("spears have a distinct silhouette from swords", () => {
38	    expect(renderSpritePixels("stone_spear")).not.toEqual(renderSpritePixels("stone_sword"));
39	  });
40	
41	  test("the knife silhouette is distinct from every sword", () => {
42	    const knife = renderSpritePixels("knife");
43	    for (const def of ITEM_DEFS) {
44	      if (!def.id.endsWith("_sword")) continue;
45	      const sword = renderSpritePixels(def.id);
46	      expect(knife).not.toEqual(sword);
47	      // The knife has no crossguard: the sword's wide row 10 stays narrow.
48	      const rowWidth = (pixels: Uint8ClampedArray, y: number) => {
49	        let count = 0;
50	        for (let x = 0; x < SPRITE_SIZE; x += 1) if (pixels[(y * SPRITE_SIZE + x) * 4 + 3] > 0) count += 1;
51	        return count;
52	      };
53	      expect(rowWidth(knife, 10)).toBeLessThan(rowWidth(sword, 10));
54	    }
55	  });
56	
57	  test("every tool/weapon material prefix has a palette", () => {
58	    // The knife and bow render from their own custom grids, not the shared
59	    // tool/sword grid + material-prefix palette, so they are exempt.
60	    const customGrid = new Set(["knife", "bow"]);
61	    for (const def of ITEM_DEFS) {
62	      if (def.kind !== "tool" && (def.kind !== "weapon" || customGrid.has(def.id))) continue;
63	      expect(MATERIAL_PALETTES[def.id.split("_")[0]]).toBeDefined();
64	    }
65	  });
66	
67	  test("unknown ids fall back to the placeholder checker", () => {
68	    const pixels = renderSpritePixels("no_such_item");
69	    expect(opaquePixelCount(pixels)).toBeGreaterThan(0);
70	  });
71	});
72	
73	describe("paintIsoBlock", () => {
74	  test("top face is brighter than the right face", () => {
75	    const pixels = paintIsoBlock(BlockId.Stone);
76	    const at = (x: number, y: number) => {
77	      const i = (y * SPRITE_SIZE + x) * 4;
78	      return pixels[i] + pixels[i + 1] + pixels[i + 2];
79	    };
80	    // (8, 4) sits on the top face; (12, 10) on the right face.
81	    expect(at(8, 4)).toBeGreaterThan(at(12, 10));
82	  });
83	
84	  test("ore cubes differ from plain stone", () => {
85	    expect(paintIsoBlock(BlockId.DiamondOre)).not.toEqual(paintIsoBlock(BlockId.Stone));
86	  });
87	
88	  test("corners stay transparent", () => {
89	    const pixels = paintIsoBlock(BlockId.Dirt);
90	    expect(pixels[3]).toBe(0); // top-left corner alpha
91	    expect(pixels[(SPRITE_SIZE - 1) * 4 + 3]).toBe(0); // top-right corner alpha
92	  });
93	});
94	
95	describe("paintGrid", () => {
96	  test("maps palette characters and leaves dots transparent", () => {
97	    const pixels = paintGrid(["xx", ".x"], { x: [10, 20, 30] });
98	    expect([pixels[0], pixels[1], pixels[2], pixels[3]]).toEqual([10, 20, 30, 255]);
99	    expect(pixels[(SPRITE_SIZE + 0) * 4 + 3]).toBe(0); // row 1 col 0 is "."
