38	function makeTypedWorld(sizeX: number, sizeY: number, sizeZ: number, seed: number, worldType: WorldType): VoxelWorld {
39	  const world = new VoxelWorld(sizeX, sizeY, sizeZ, seed);
40	  generateWorld(world, worldType);
41	  return world;
42	}
