44	const GROUND_BLOCKS = new Set<number>([BlockId.Grass, BlockId.Sand, BlockId.Dirt, BlockId.Stone, BlockId.Cobblestone, BlockId.Snow]);
45	
46	/** Highest terrain (ground) block in a column, ignoring trees/water/air — the visible surface. */
47	function groundHeight(world: VoxelWorld, x: number, z: number): number {
48	  for (let y = world.sizeY - 1; y >= 0; y -= 1) {
49	    if (GROUND_BLOCKS.has(world.get(x, y, z))) return y;
50	  }
51	  return 0;
52	}
