60	describe("worldgen determinism", () => {
61	  test.each([
62	    [1337, "2037297fd8b8269fa984f907b84bcf3b185e4c261ae4a93b089de0178cc510d2"],
63	    [1, "c55a0b3395d2a95643ded6af66d49bbea4de44d045f5a812f625f397f5b377d7"],
64	    [999999937, "4407190a254fdb5fa7f00aff69ba75b6c624bac6bc27096934e713506979384c"]
65	  ])("128x150x128 world for seed %d is byte-identical", (seed, expected) => {
66	    expect(hashBytes(makeWorld(128, 150, 128, seed).blocks)).toBe(expected);
67	  });
68	
69	  test(
70	    "full-size 512x150x512 world for seed 1337 is byte-identical (the real save-compat surface)",
71	    () => {
72	      expect(hashBytes(fullWorld().blocks)).toBe("3675b077d5a0a677aadf7a4b5e781cfb38cec2eef6aa62c676e3a9f0f48a404f");
73	    },
74	    { timeout: 60000 }
75	  );
76	
77	  // Probes that survive a legitimate re-baseline: they describe the shape of the
78	  // world rather than its exact bytes, and localize a failure when the hash differs.
79	  test("structural probes for seed 1337", () => {
80	    const world = fullWorld();
81	
82	    // Bedrock floor everywhere and border walls up to y=14.
83	    expect(world.get(5, 0, 5)).toBe(BlockId.Bedrock);
84	    expect(world.get(300, 0, 300)).toBe(BlockId.Bedrock);
85	    expect(world.get(0, 10, 100)).toBe(BlockId.Bedrock);
86	    expect(world.get(511, 14, 200)).toBe(BlockId.Bedrock);
87	    expect(world.get(200, 14, 0)).toBe(BlockId.Bedrock);
88	
89	    // Biome field samples.
90	    expect(world.getBiome(1, 1)).toBe(BiomeId.Forest);
91	    expect(world.getBiome(1, 277)).toBe(BiomeId.Desert);
92	    expect(world.getBiome(400, 100)).toBe(BiomeId.Mountains);
93	
94	    // Terrain heights at sample columns ((64,64) tops out in a tree canopy).
95	    expect(world.highestSolidY(64, 64)).toBe(49);
96	    expect(world.highestSolidY(256, 256)).toBe(28);
97	    expect(world.highestSolidY(400, 100)).toBe(104);
98	
99	    // Snow caps above the snow line.
100	    expect(world.get(400, 104, 100)).toBe(BlockId.Snow);
101	
102	    // Sea-level fill: a column whose floor is below sea level holds water at y=43.
103	    expect(world.highestSolidY(1, 277)).toBe(30);
104	    expect(world.get(1, 43, 277)).toBe(BlockId.Water);
105	
106	    // Lava pools in the deepest caves only — present, and never above lavaLevel.
107	    let lavaCells = 0;
108	    let maxLavaY = -1;
109	    const layer = world.sizeX * world.sizeZ;
110	    for (let i = 0; i < world.blocks.length; i += 1) {
