1	import * as THREE from "three";
2	import { BlockId, doorState, isDoorBlock } from "@/lib/world";
3	import { EXPLOSION_DAMAGE_PER_POWER, TNT_CHAIN_FUSE_MAX_SECONDS, TNT_CHAIN_FUSE_MIN_SECONDS, TNT_EXPLOSION_POWER, TNT_FUSE_SECONDS } from "@/lib/game/config";
4	import type { EmitGameEvent, GameState } from "../state";
5	
6	/**
7	 * Everything an explosion needs from the engine. A subset of `MobTickDeps`, so
8	 * the creeper branch in mobAI can pass its `deps` straight through.
9	 */
10	export type ExplosionDeps = {
11	  applyDamage: (amount: number) => void;
12	  rng: () => number;
13	  emit: EmitGameEvent;
14	};
15	
16	/** Blocks the blast can never break (mirrors the mining unbreakables + worldgen hazards). */
17	function isBlastproof(block: BlockId): boolean {
18	  return block === BlockId.Bedrock || block === BlockId.Spawner || block === BlockId.Lava;
19	}
20	
21	/** Higher = harder to destroy: the blast strength at a cell must exceed this to break it. */
22	function blastResistance(block: BlockId): number {
23	  switch (block) {
24	    case BlockId.Stone:
25	    case BlockId.Cobblestone:
26	    case BlockId.Brick:
27	    case BlockId.MossyCobblestone:
28	    case BlockId.Furnace:
29	    case BlockId.CoalOre:
30	    case BlockId.SliverOre:
31	    case BlockId.RubyOre:
32	    case BlockId.GoldOre:
33	    case BlockId.SapphireOre:
34	    case BlockId.DiamondOre:
35	      return 2.5;
36	    case BlockId.Chest:
37	      return 1.2;
38	    default:
39	      return 0.4; // dirt, sand, wood, planks, leaves, glass, doors, crops, torches, ...
40	  }
41	}
42	
43	const scratchKnock = new THREE.Vector3();
44	
45	/**
46	 * An explosion centered at (cx,cy,cz). It destroys blocks within `power` (a
47	 * distance falloff weighed against each block's blast resistance), then damages
48	 * the player and mobs out to twice that radius with the same falloff, and emits
49	 * one `explosion` event for the renderer/audio.
50	 *
51	 * It rides the existing single-block edit chokepoint: each destroyed cell goes
52	 * through `blockChanges.set` (which relights locally and records the save delta),
53	 * and `worldMeshDirty` is set **once** so the whole crater costs a single remesh.
54	 * It never removes mobs — it only lowers hp — so it is safe to call from inside
55	 * the mob tick loop; the caller sweeps any mob that reaches 0 hp.
56	 */
57	export function explode(state: GameState, cx: number, cy: number, cz: number, power: number, deps: ExplosionDeps): void {
58	  const { world } = state;
59	  const radius = Math.ceil(power);
60	  const bx = Math.floor(cx);
61	  const by = Math.floor(cy);
62	  const bz = Math.floor(cz);
63	  let changed = false;
64	
65	  for (let dx = -radius; dx <= radius; dx += 1) {
66	    for (let dy = -radius; dy <= radius; dy += 1) {
67	      for (let dz = -radius; dz <= radius; dz += 1) {
68	        const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
69	        if (dist > power) continue;
70	        const x = bx + dx;
71	        const y = by + dy;
72	        const z = bz + dz;
73	        if (!world.inBounds(x, y, z) || y <= 1) continue;
74	        const block = world.get(x, y, z) as BlockId;
75	        if (block === BlockId.Air || isBlastproof(block)) continue;
76	        if (power * (1 - dist / power) <= blastResistance(block)) continue;
77	
78	        if (block === BlockId.Tnt) {
79	          // Chain reaction: light neighboring TNT on a short randomized fuse
80	          // instead of vaporizing it, so blasts ripple.
81	          const idx = world.index(x, y, z);
82	          if (!state.primedTnt.has(idx)) {
83	            state.primedTnt.set(idx, TNT_CHAIN_FUSE_MIN_SECONDS + deps.rng() * (TNT_CHAIN_FUSE_MAX_SECONDS - TNT_CHAIN_FUSE_MIN_SECONDS));
84	            deps.emit({ type: "tntPrimed", x, y, z });
85	          }
86	          continue;
87	        }
88	        if (isDoorBlock(block)) {
89	          const door = doorState(block)!;
90	          const otherY = door.upper ? y - 1 : y + 1;
91	          state.blockChanges.set(x, y, z, BlockId.Air);
92	          if (isDoorBlock(world.get(x, otherY, z) as BlockId)) state.blockChanges.set(x, otherY, z, BlockId.Air);
93	        } else {
94	          state.blockChanges.set(x, y, z, BlockId.Air);
95	        }
96	        changed = true;
97	      }
98	    }
99	  }
100	  if (changed) state.worldMeshDirty = true;
101	
102	  const damageRange = power * 2;
103	  const peak = power * EXPLOSION_DAMAGE_PER_POWER;
104	
105	  // Player: armor-aware damage + knockback away from the blast.
106	  const { player } = state;
107	  const pdist = Math.hypot(player.position.x - cx, player.position.y - cy, player.position.z - cz);
108	  if (pdist < damageRange) {
109	    const falloff = 1 - pdist / damageRange;
110	    deps.applyDamage(Math.max(1, Math.round(peak * falloff)));
111	    if (pdist > 0.001) {
112	      scratchKnock
113	        .set(player.position.x - cx, player.position.y - cy, player.position.z - cz)
114	        .normalize()
115	        .multiplyScalar(power * falloff);
116	      player.velocity.x += scratchKnock.x;
117	      player.velocity.z += scratchKnock.z;
118	      player.velocity.y = Math.max(player.velocity.y, Math.abs(scratchKnock.y) + 2);
119	    }
120	  }
121	
122	  // Mobs: damage only — the caller removes any that reach 0 hp (so this is safe
123	  // to run mid mob-loop). A light directional shove reads as the blast pushing them.
124	  for (const mob of state.mobs) {
125	    const mdist = Math.hypot(mob.position.x - cx, mob.position.y - cy, mob.position.z - cz);
126	    if (mdist >= damageRange) continue;
127	    mob.hp -= Math.max(1, Math.round(peak * (1 - mdist / damageRange)));
128	    if (mdist > 0.001) mob.direction.set(mob.position.x - cx, 0, mob.position.z - cz).normalize();
129	  }
130	
131	  deps.emit({ type: "explosion", x: cx, y: cy, z: cz, power });
132	}
133	
134	/** Lights the TNT block at (x,y,z) on a full fuse (no-op if already lit). */
135	export function primeTnt(state: GameState, x: number, y: number, z: number, emit: EmitGameEvent): void {
136	  const idx = state.world.index(x, y, z);
137	  if (state.primedTnt.has(idx)) return;
138	  state.primedTnt.set(idx, TNT_FUSE_SECONDS);
139	  emit({ type: "tntPrimed", x, y, z });
140	}
141	
142	/**
143	 * Counts down lit TNT and detonates it. A TNT block mined or replaced before its
144	 * fuse runs out is silently dropped (the block check). Detonations run after the
145	 * countdown pass so a blast's chain-priming can't mutate the map mid-iteration.
146	 */
147	export function tickPrimedTnt(state: GameState, dt: number, deps: ExplosionDeps): void {
148	  if (state.primedTnt.size === 0) return;
149	  const { world } = state;
150	  const layer = world.sizeX * world.sizeZ;
151	  const detonations: Array<[number, number, number]> = [];
152	
153	  for (const [idx, timer] of state.primedTnt) {
154	    const y = Math.floor(idx / layer);
155	    const rem = idx - y * layer;
156	    const z = Math.floor(rem / world.sizeX);
157	    const x = rem - z * world.sizeX;
158	    if (world.get(x, y, z) !== BlockId.Tnt) {
159	      state.primedTnt.delete(idx); // mined or overwritten → forget it
160	      continue;
161	    }
162	    const next = timer - dt;
163	    if (next > 0) {
164	      state.primedTnt.set(idx, next);
165	    } else {
166	      state.primedTnt.delete(idx);
167	      detonations.push([x, y, z]);
168	    }
169	  }
170	
171	  for (const [x, y, z] of detonations) {
172	    state.blockChanges.set(x, y, z, BlockId.Air);
173	    state.worldMeshDirty = true;
174	    explode(state, x + 0.5, y + 0.5, z + 0.5, TNT_EXPLOSION_POWER, deps);
175	  }
176	}

