38	  moveSpeed: number;
39	  detectRange: number;
40	  attackDamage: number;
41	  attackCooldown: number;
42	  attackTimer: number;
43	  halfHeight: number;
44	  bobSeed: number;
45	  /** Seconds left "in love" after being fed; pairs with another to breed. */
46	  fedTimer: number;
47	  /** Seconds left as a baby; > 0 means a scaled-down, no-drop juvenile. */
48	  ageTimer: number;
49	  /** Boss-only: seconds until the next minion summon (session-only, never saved). */
50	  summonTimer?: number;
51	  /** Creeper-only: seconds left on a lit fuse (>0 means primed); detonates at 0. Session-only. */
52	  fuseTimer?: number;
53	};
