58	 * the hit filter (player arrows hit mobs, mob arrows hit the player).
59	 */
60	export type ProjectileState = {
61	  id: number;
62	  position: THREE.Vector3;
63	  /** m/s; gravity-integrated each step. yaw/pitch are derived from it for the renderer. */
64	  velocity: THREE.Vector3;
