147	  /** Voxel index of the chest open in the inventory panel, or null. */
148	  openContainerIndex: number | null;
149	  /** Worldgen dungeon chest voxel indices (session; re-derived from the seed each load). */
150	  dungeonChestIndices: Set<number>;
